struct point { int value; };
template <class Char>
struct ffmt::formatter<point, Char> : ffmt::formatter<int, Char> {
  template <class Context>
  auto format(const point& p, Context& ctx) const {
    return ffmt::formatter<int, Char>::format(p.value, ctx);
  }
};
